/**
 * Checks if the report has only one participant and returns true if the current user is the only one left.
 */
function isLastGroupMember(report: OnyxEntry<Report>): boolean {
    if (!report || !report.participants) {
        return false;
    }

    const participants = Object.keys(report.participants);
    return participants.length === 1 && participants.includes(String(currentUserAccountID));
}
